+.mobile-nav a:hover{background: rgba(255,255,255,.10); text-decoration:none}
+
+/* Banner */
+.banner{
+  background: linear-gradient(90deg, rgba(254,172,50,.18), rgba(254,172,50,.06));
+  border-bottom: 1px solid var(--olh-border);
+}
+.banner .inner{
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: var(--s-3);
+  padding: var(--s-3) 0;
+}
+.banner .title{
+  font-weight: 750;
+  letter-spacing: .01em;
+}
+.banner a{
+  color: var(--olh-ink);
+  font-weight: 650;
+  text-decoration:none;
+  border-bottom: 1px solid rgba(10,10,35,.25);
+}
+.banner a:hover{border-bottom-color: rgba(10,10,35,.55)}
+
+/* Page */
+main{padding: var(--s-6) 0}
+@media (max-width: 640px){main{padding: var(--s-5) 0}}
+
+.section-head{
+  display:flex;
+  align-items:flex-end;
+  justify-content:space-between;
+  gap: var(--s-4);
+  margin-bottom: var(--s-4);
+}
+.kicker{color: var(--olh-muted); font-weight: 650; letter-spacing: .02em; text-transform: uppercase; font-size: 12px}
+h1,h2,h3{margin:0}
+h1{font-size: clamp(28px, 3.4vw, 44px); line-height: 1.1; letter-spacing: -0.02em}
+h2{font-size: clamp(20px, 2.1vw, 28px); line-height: 1.15; letter-spacing: -0.02em}
+h3{font-size: 18px; line-height:1.2; letter-spacing: -0.01em}
+.lede{color: var(--olh-ink-2); max-width: 72ch}
+
+/* Cards */
+.grid{
+  display:grid;
+  gap: var(--s-4);
+}
+.grid.cols-2{grid-template-columns: 1fr}
+@media (min-width: 900px){.grid.cols-2{grid-template-columns: 1.2fr .8fr}}
+
+.grid.cards{grid-template-columns: 1fr}
+@media (min-width: 780px){.grid.cards{grid-template-columns: repeat(2, minmax(0,1fr))}}
+@media (min-width: 1180px){.grid.cards{grid-template-columns: repeat(3, minmax(0,1fr))}}
+
+.card{
+  background: white;
+  border: 1px solid var(--olh-border);
+  border-radius: var(--radius-md);
+  overflow:hidden;
+  box-shadow: var(--shadow-sm);
+}
+.card:hover{box-shadow: var(--shadow-md)}
+.thumb{
+  position:relative;
+  height: 160px;
+  background: linear-gradient(135deg, oklch(26% 0.05 275), oklch(22% 0.04 250));
+}
+.thumb img{width:100%; height:100%; object-fit:cover; display:block}
+.tag{
+  position:absolute;
+  left: var(--s-3);
+  top: var(--s-3);
+  background: rgba(10,10,35,.88);
+  border: 1px solid rgba(255,255,255,.16);
+  color: rgba(255,255,255,.95);
+  padding: 6px 10px;
+  border-radius: 999px;
+  font-size: 12px;
+  font-weight: 700;
+  letter-spacing: .02em;
+}
+.tag a{color: inherit; text-decoration:none}
+.tag a:hover{text-decoration:underline}
+
+.card-body{padding: var(--s-4)}
+.card-title{margin: 8px 0 0; font-weight: 800}
+.card-title a{color: inherit; text-decoration:none}
+.card-title a:hover{text-decoration:underline}
+.meta{
+  display:flex;
+  align-items:center;
+  gap: 10px;
+  margin-top: var(--s-3);
+  color: var(--olh-muted);
+  font-size: 13px;
+}
+.avatar{
+  width: 28px;
+  height: 28px;
+  border-radius: 999px;
+  border: 1px solid var(--olh-border);
+  background: linear-gradient(135deg, oklch(78% 0.06 275), oklch(86% 0.02 275));
+  display:grid;
+  place-items:center;
+  color: var(--olh-ink);
+  font-weight: 800;
+}
+.meta strong{color: var(--olh-ink); font-weight: 700}
+.dot{opacity:.6}
+
+/* Featured */
+.featured{
+  display:grid;
+  grid-template-columns: 1fr;
+  gap: var(--s-4);
+}
+@media (min-width: 900px){
+  .featured{grid-template-columns: 1.35fr .65fr}
+}
+
+.featured .lead{
+  border-radius: 22px;
+  overflow:hidden;
+  border: 1px solid var(--olh-border);
+  background: white;
+  box-shadow: var(--shadow-md);
+}
+.featured .lead .thumb{height: 280px}
+.featured .lead .card-body{padding: var(--s-5)}
+.featured .lead .card-title{font-size: clamp(22px, 2.2vw, 30px)}
+
+.aside{
+  border-radius: 22px;
+  border: 1px solid var(--olh-border);
+  background: var(--olh-surface-2);
+  padding: var(--s-4);
+}
+.aside h3{margin-bottom: var(--s-2)}
+.aside p{margin: 0; color: var(--olh-ink-2)}
+.aside .cta-row{display:flex; flex-wrap:wrap; gap: 10px; margin-top: var(--s-3)}
+
+/* Buttons */
+.btn{
+  display:inline-flex;
+  align-items:center;
+  justify-content:center;
+  gap: 10px;
+  padding: 12px 16px;
+  border-radius: 999px;
+  border: 1px solid var(--olh-border);
+  background: white;
+  color: var(--olh-ink);
+  font-weight: 750;
+  cursor:pointer;
+}
+.btn:hover{box-shadow: var(--shadow-sm)}
+.btn-primary{
+  border-color: rgba(10,10,35,.18);
+  background: linear-gradient(180deg, var(--olh-amber), oklch(72% 0.16 75));
+  color: var(--olh-navy);
+}
+.btn-primary:hover{text-decoration:none; filter: brightness(0.98)}
+.btn-ghost{
+  background: transparent;
+  color: var(--olh-ink);
+}
+
+/* Learn page blocks */
+.panel{
+  background: white;
+  border: 1px solid var(--olh-border);
+  border-radius: 22px;
+  box-shadow: var(--shadow-sm);
+  padding: var(--s-5);
+}
+@media (max-width: 640px){.panel{padding: var(--s-4)}}
+
+.list{
+  display:grid;
+  gap: 12px;
+  margin-top: var(--s-3);
+}
+.item{
+  display:flex;
+  align-items:flex-start;
+  gap: 12px;
+  padding: 12px 14px;
+  border-radius: 16px;
+  border: 1px solid var(--olh-border);
+  background: var(--olh-surface);
+}
+.icon{
+  width: 34px;
+  height: 34px;
+  border-radius: 12px;
+  background: linear-gradient(180deg, rgba(254,172,50,.28), rgba(254,172,50,.10));
+  border: 1px solid rgba(10,10,35,.10);
+  display:grid;
+  place-items:center;
+  color: var(--olh-navy);
+  font-weight: 900;
+}
+.item .txt{flex:1}
+.item .txt .title{font-weight: 800}
+.item .txt .sub{color: var(--olh-muted); font-size: 13px; margin-top: 2px}
+
+/* Donate */
+.donate-hero{
+  display:grid;
+  grid-template-columns: 1fr;
+  gap: var(--s-4);
+}
+@media (min-width: 980px){
+  .donate-hero{grid-template-columns: 1.15fr .85fr}
+}
+
+.tabs{display:flex; gap: 10px; flex-wrap:wrap}
+.tab{
+  padding: 10px 14px;
+  border-radius: 999px;
+  border: 1px solid var(--olh-border);
+  background: white;
+  font-weight: 800;
+  cursor:pointer;
+  min-width: 64px;
+}
+.tab[aria-pressed="true"]{
+  border-color: rgba(10,10,35,.16);
+  background: linear-gradient(180deg, var(--olh-amber), oklch(72% 0.16 75));
+  color: var(--olh-navy);
+}
+.donate-box{background: white; border:1px solid var(--olh-border); border-radius: 22px; box-shadow: var(--shadow-md); padding: var(--s-5)}
+.donate-desc{margin: var(--s-3) 0 0; color: var(--olh-ink-2)}
+.subtle{color: var(--olh-muted); font-size: 13px}
+.split{display:grid; grid-template-columns: 1fr; gap: var(--s-4)}
+@media (min-width: 900px){.split{grid-template-columns: 1fr 1fr}}
+
+/* Accordion */
+.accordion{border: 1px solid var(--olh-border); border-radius: 22px; overflow:hidden; background: white}
+.acc-item + .acc-item{border-top: 1px solid var(--olh-border)}
+.acc-btn{
+  width:100%;
+  display:flex;
+  align-items:center;
+  justify-content:space-between;
+  gap: var(--s-3);
+  padding: 16px 18px;
+  background: transparent;
+  border:0;
+  cursor:pointer;
+  text-align:left;
+  font-weight: 800;
+  color: var(--olh-ink);
+}
+.chev{width: 18px; height: 18px; transition: transform .18s ease}
+.acc-item[data-open="true"] .chev{transform: rotate(180deg)}
+.acc-panel{
+  max-height: 0;
+  overflow:hidden;
+  transition: max-height .22s ease;
+}
+.acc-panel .inner{padding: 0 18px 16px; color: var(--olh-ink-2)}
+
+/* Popular tags row */
+.tag-row{
+  display:flex;
+  gap: 10px;
+  overflow:auto;
+  padding: 6px 2px 10px;
+  scroll-snap-type: x mandatory;
+}
+.pill{
+  scroll-snap-align:start;
+  display:inline-flex;
+  align-items:center;
+  gap: 10px;
+  border-radius: 999px;
+  padding: 10px 12px;
+  border: 1px solid var(--olh-border);
+  background: white;
+  white-space: nowrap;
+  font-weight: 750;
+  color: var(--olh-ink);
+}
+.pill small{color: var(--olh-muted); font-weight: 700}
+
+/* Footer */
+.footer{
+  border-top: 1px solid var(--olh-border);
+  background: var(--olh-surface-2);
+  padding: var(--s-7) 0;
+}
+.footer-grid{display:grid; gap: var(--s-5)}
+@media (min-width: 900px){.footer-grid{grid-template-columns: 1.2fr .8fr}}
+.footer h3{margin-bottom: 10px}
+.footer p{margin:0; color: var(--olh-ink-2)}
+.footer .links{display:flex; flex-wrap:wrap; gap: 10px; margin-top: 12px}
+.footer .links a{
+  padding: 8px 10px;
+  border: 1px solid var(--olh-border);
+  border-radius: 999px;
+  background: white;
+  color: var(--olh-ink);
+  font-weight: 650;
+}
+
+/* Utility */
+.mt-6{margin-top: var(--s-6)}
+.mt-4{margin-top: var(--s-4)}
+.sr-only{position:absolute; width:1px; height:1px; padding:0; margin:-1px; overflow:hidden; clip:rect(0,0,0,0); white-space:nowrap; border:0}
+
+@media (prefers-reduced-motion: reduce){
+  *{scroll-behavior:auto !important}
+  .acc-panel{transition:none}
+  .chev{transition:none}
+}
+
*** End Patch
PATCH"}

